mapper.select:
SELECT SUM(payment_amount) FROM biz_payment_order


        AND payment_no LIKE CONCAT('%', #{paymentNo}, '%')


        AND supplier_id = #{supplierId}


        AND supplier_name LIKE CONCAT('%', #{supplierName}, '%')


        AND payment_time BETWEEN #{paymentTime[0], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP} AND
        #{paymentTime[1], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP}


        AND payment_method = #{paymentMethod}


        AND is_invoiced = #{isInvoiced}


        AND create_time BETWEEN #{createTime[0], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP} AND
        #{createTime[1], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP}

    and deleted = false
